"import re\n\nwith open('data/sql/haitacz0.sql', 'r', encoding='utf-8', errors='ignore') as f:\n    for line in f:\n        if line.startswith('INSERT INTO `maps` VALUES (1, '):\n            npcs = re.findall(r'\\[(-?\\d+),\\\\\"([^\\\\\"]+)\\\\\",\\\\\"([^\\\\\"]+)\\\\\"', line)\n            for n in npcs:\n                print(f\"ID: {n[0]}, Name: {n[1]}, Role: {n[2]}\")\n            break\n"